const axios = require('axios')
const yts = require('yt-search')

function convertid(url) {
  const regex = /(?:youtube\.com\/(?:[^\/]+\/.+\/|(?:v|embed|watch|shorts)\/|.*[?&]v=)|youtu\.be\/)([a-zA-Z0-9_-]{11})(?:[&?]|$)/
  const match = url.match(regex)
  return match ? match[1] : null
}

async function resolveid(input) {
  try {
    const direct = convertid(input)
    if (direct) return direct

    const search = await axios.get(
      `https://test.flvto.online/search/?q=${encodeURIComponent(input)}`,
      {
        headers: {
          'User-Agent': 'Mozilla/5.0 (Linux; Android 10)',
          origin: 'https://v5.ytmp4.is',
          referer: 'https://v5.ytmp4.is/'
        }
      }
    )

    if (!search.data.items || !search.data.items.length)
      return null

    return search.data.items[0].id
  } catch {
    return null
  }
}

async function convert(input, format = 'mp3') {
  try {
    const youtube_id = await resolveid(input)
    if (!youtube_id)
      return {
        status: false,
        message: "Video tidak ditemukan!"
      }

    const converter = await axios.post(
      'https://ht.flvto.online/converter',
      { id: youtube_id, fileType: format },
      {
        headers: {
          'User-Agent': 'Mozilla/5.0 (Linux; Android 10)',
          'Content-Type': 'application/json',
          origin: 'https://ht.flvto.online',
          referer: `https://ht.flvto.online/button?url=https://www.youtube.com/watch?v=${youtube_id}&fileType=${format}`
        }
      }
    )

    const data = converter.data
    const ytdata = await yts(`https://youtube.com/watch?v=${youtube_id}`)

    if (format === 'mp3') {
      return {
        status: true,
        creator: "@denzy-official/youtube_scraper",
        metadata: ytdata.all[0],
        download: {
          type: 'mp3',
          title: data.title,
          filesize: data.filesize,
          duration: data.duration,
          url: data.link,
          filename: `${data.title}.mp3`
        }
      }
    }

    if (format === 'mp4') {
      if (!Array.isArray(data.formats) || !data.formats.length)
        return {
          status: false,
          message: "Format video tidak tersedia!"
        }

      const sorted = data.formats.sort((a, b) => b.height - a.height)

      const selected =
        sorted.find(v => v.qualityLabel === '720p') ||
        sorted[0]

      return {
        status: true,
        creator: "@denzy-official/youtube_scraper",
        metadata: ytdata.all[0],
        download: {
          type: 'mp4',
          title: data.title,
          quality: selected.qualityLabel,
          url: selected.url,
          filename: `${data.title}.mp4`
        }
      }
    }

  } catch {
    return {
      status: false,
      message: "Terjadi kesalahan pada sistem!"
    }
  }
}

async function ytmp3(input) {
  return convert(input, 'mp3')
}

async function ytmp4(input) {
  return convert(input, 'mp4')
}

async function search(query) {
  try {
    const data = await yts(query)

    return {
      status: true,
      creator: "@denzy-official/youtube_scraper",
      results: data.videos.slice(0, 10).map(v => ({
        title: v.title,
        url: v.url,
        duration: v.timestamp,
        views: v.views,
        author: v.author.name,
        thumbnail: v.thumbnail
      }))
    }
  } catch (err) {
    return {
      status: false,
      message: "Gagal melakukan pencarian!"
    }
  }
}

module.exports = {
  ytmp3,
  ytmp4,
  search
}
